function migrate(v){return coreEnsureSchema6(v)}
function load(){for(const key of [STORAGE,...LEGACY_KEYS]){try{const raw=localStorage.getItem(key);if(raw)return migrate(JSON.parse(raw))}catch(e){}}return migrate(clone(sample))}
let state=load(),dbPromise=null,scrollPos={home:0,account:0,analysis:0,future:0},settingsDraft=null;
function dataSignature(v){return JSON.stringify({appId:v.appId,dataId:v.dataId,schemaVersion:v.schemaVersion,profile:v.profile,settings:v.settings,accounts:v.accounts,years:v.years,accountYears:v.accountYears,dividendsByAsset:v.dividendsByAsset,runtime:v.runtime,ledger:v.ledger,snapshots:v.snapshots,archives:v.archives,extensions:v.extensions,lastUpdated:v.lastUpdated})}
let lastSignature=dataSignature(state);
function openDB(){if(!('indexedDB'in window))return Promise.reject();if(dbPromise)return dbPromise;dbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open(DB_NAME,1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains(DB_STORE))req.result.createObjectStore(DB_STORE)};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});return dbPromise}
async function putDB(){try{const db=await openDB();await new Promise((resolve,reject)=>{const tx=db.transaction(DB_STORE,'readwrite');tx.objectStore(DB_STORE).put(clone(state),DB_KEY);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}catch(e){}}
async function hydrateDB(){const startedSignature=dataSignature(state);try{const db=await openDB();const saved=await new Promise((resolve,reject)=>{const tx=db.transaction(DB_STORE,'readonly'),store=tx.objectStore(DB_STORE),r=store.get(DB_KEY),r2=store.get(LEGACY_DB_KEY);let a,b,done=0;const finish=()=>{if(++done===2)resolve([a,b].filter(Boolean).sort((x,y)=>(y.meta?.revision||0)-(x.meta?.revision||0))[0])};r.onsuccess=()=>{a=r.result;finish()};r.onerror=finish;r2.onsuccess=()=>{b=r2.result;finish()};r2.onerror=finish});const unchanged=dataSignature(state)===startedSignature;if(saved&&unchanged&&(saved.meta?.revision||0)>(state.meta?.revision||0)){state=migrate(saved);lastSignature=dataSignature(state);try{localStorage.setItem(STORAGE,JSON.stringify(state))}catch(_){ }renderAll(true);toast('기기 저장 데이터를 불러왔어요')}}catch(e){}}
