function prepareHolding(accountKey,raw={},previous={}){const a=state.accounts[accountKey],stamp=isoNow(),base={...plainObject(previous),...plainObject(raw)};return {...base,id:String(base.id||entityUid(`holding-${accountKey}`)),accountId:a.id,status:'active',entityVersion:Math.max(1,Number(base.entityVersion)||1),createdAt:validIso(base.createdAt||stamp),updatedAt:stamp,extensions:plainObject(base.extensions),name:String(base.name||'').slice(0,60),qty:Number(base.qty)||0,value:Number(base.value)||0,cost:Number(base.cost)||0,dividend:Number(base.dividend)||0,realized:Number(base.realized)||0}}
function archiveMissingHoldings(accountKey,nextRows=[],reason='snapshot-replaced'){coreEnsureSchema6(state);const a=state.accounts[accountKey],names=new Set(nextRows.map(r=>String(r.name||'').trim()).filter(Boolean));for(const h of a.holdings||[]){if(names.has(String(h.name||'').trim()))continue;state.archives.holdings.push({archiveId:entityUid('holding-archive'),entityType:'holding',entityId:h.id,accountId:a.id,archivedAt:isoNow(),reason,data:clone({...h,status:'inactive'})})}}
function accountTotal(a){return (Number(a.cash)||0)+a.holdings.reduce((s,h)=>s+(Number(h.value)||0),0)}
function totalAsset(){return accountTotal(state.accounts.pension)+accountTotal(state.accounts.irp)}
function totalPrincipal(){return (Number(state.accounts.pension.principal)||0)+(Number(state.accounts.irp.principal)||0)}
function accountReturn(a){return a.principal?(accountTotal(a)/a.principal-1)*100:0}
function ensureYear(y=CURRENT_YEAR){if(!state.years[y])state.years[y]={start:totalAsset(),end:totalAsset(),cumulative:totalPrincipal(),contribution:0,operating:0,realized:0,return:0,dividend:0,reinvested:0,monthly:Array(12).fill(0)};return state.years[y]}
