function bindCarousel(){const track=document.getElementById('homeTrack');if(!track)return;let index=0,startX=0;const set=i=>{index=clamp(i,0,1);track.style.transform=`translateX(${-50*index}%)`;document.querySelectorAll('#homeCarousel .dot').forEach((d,j)=>d.classList.toggle('active',j===index))};document.querySelectorAll('#homeCarousel .dot').forEach(d=>d.onclick=()=>set(Number(d.dataset.slide)));track.onpointerdown=e=>{startX=e.clientX;track.setPointerCapture(e.pointerId)};track.onpointerup=e=>{const dx=e.clientX-startX;if(Math.abs(dx)>45)set(index+(dx<0?1:-1))}}
function renderAccount(){const key=state.ui.accountView,a=state.accounts[key],total=accountTotal(a),profit=total-a.principal,riskValue=key==='irp'?a.holdings.filter(h=>h.risk!==false).reduce((s,h)=>s+h.value,0):0,risk=total?riskValue/total*100:0;const holdings=a.holdings.length?a.holdings.map((h,i)=>{const p=h.value-h.cost,r=h.cost?p/h.cost*100:0,cls=state.settings.assetClasses.find(c=>c.id===h.class)?.name||'미분류';return `<div class="holdingRow"><button class="holdingBtn" data-holding="${i}"><div><b title="${esc(h.name)}">${esc(h.name)}</b><small>${esc(cls)} · ${Number(h.qty||0).toLocaleString('ko-KR')}주</small></div><strong>${fmt(h.value)}<small class="${p>=0?'good':'bad'}">${p>=0?'+':''}${fmt(p)} · ${pct(r)}</small></strong></button><div class="holdingDetail" id="holding-${i}"><div class="holdingDetailInner"><div class="holdingDetailGrid"><div>원금<b>${fmt(h.cost)}</b></div><div>평가손익<b class="${p>=0?'good':'bad'}">${p>=0?'+':''}${fmt(p)}</b></div><div>누적 분배금<b>${fmt(h.dividend||0)}</b></div><div>확정손익<b>${fmt(h.realized||0)}</b></div></div></div></div></div>`}).join(''):`<div class="empty"><div class="emptyIcon">＋</div><b>아직 등록된 자산이 없어요</b><p>빠른 입력에서 자산현황을 붙여넣으면 계좌 분석이 시작돼요.</p></div>`;
 document.getElementById('account').innerHTML=`<div class="segment two"><i class="segmentIndicator ${key==='irp'?'right':''}"></i><button data-account="pension" class="${key==='pension'?'active':''}">연금저축</button><button data-account="irp" class="${key==='irp'?'active':''}">IRP</button></div><div class="accountWrap" id="accountWrap"><div class="stack"><div class="card hero"><div class="eyebrow">${esc(a.name)} 현재 자산</div><div class="money small">${fmt(total)}</div>${total?`<div class="${profit>=0?'good':'bad'}" style="font-weight:950">${profit>=0?'+':''}${fmt(profit)} · ${pct(accountReturn(a))}</div>`:`<div class="tiny">첫 자산현황을 입력하세요</div>`}<div class="three"><div class="miniMetric"><small>납입원금</small><b>${man(a.principal)}</b></div><div class="miniMetric"><small>평가손익</small><b>${man(profit)}</b></div><div class="miniMetric"><small>현금</small><b>${man(a.cash)}</b></div></div>${key==='irp'&&total?`<div class="status ${risk>68?'warn':''}">위험자산 ${risk.toFixed(1)}% · 안전자산 ${(100-risk).toFixed(1)}% · 한도까지 ${Math.max(0,70-risk).toFixed(1)}%p</div>`:''}</div><div class="card holdings">${holdings}</div></div></div>`;
 document.querySelectorAll('[data-account]').forEach(b=>b.onclick=()=>switchAccount(b.dataset.account));document.querySelectorAll('[data-holding]').forEach(b=>b.onclick=()=>document.getElementById(`holding-${b.dataset.holding}`).classList.toggle('open'));bindAccountSwipe();}
function switchAccount(key){if(key===state.ui.accountView)return;state.ui.accountView=key;renderAccount();save()}
function bindAccountSwipe(){const el=document.getElementById('accountWrap');if(!el)return;let x=0,active=false;el.onpointerdown=e=>{x=e.clientX;active=true};el.onpointerup=e=>{if(!active)return;active=false;const dx=e.clientX-x;if(Math.abs(dx)>60)switchAccount(dx<0?'irp':'pension')};el.onpointercancel=()=>active=false}
function linePath(points){return points.map((p,i)=>`${i?'L':'M'} ${p.x.toFixed(1)} ${p.y.toFixed(1)}`).join(' ')}
function buildChart(data,{xValue,yValue,cValue,xLabels,yLabels,idPrefix}){const W=620,H=250,pad={l:58,r:18,t:18,b:35},max=Math.max(...data.map(d=>Math.max(yValue(d),cValue(d))),1),min=0,x=(i)=>pad.l+(W-pad.l-pad.r)*(data.length===1?.5:i/(data.length-1)),y=v=>pad.t+(H-pad.t-pad.b)*(1-(v-min)/(max-min));const pts=data.map((d,i)=>({x:x(i),y:y(yValue(d)),cy:y(cValue(d))}));const grid=[0,.5,1].map(t=>{const yy=pad.t+(H-pad.t-pad.b)*(1-t),v=max*t;return `<line class="gridLine" x1="${pad.l}" x2="${W-pad.r}" y1="${yy}" y2="${yy}"></line><text class="axisText" x="${pad.l-8}" y="${yy+3}" text-anchor="end">${man(v)}</text>`}).join('');const labels=xLabels.map(([i,label])=>`<text class="axisText" x="${x(i)}" y="${H-10}" text-anchor="middle">${label}</text>`).join('');return {W,H,pad,max,pts,svg:`<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="areaFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#176fe5" stop-opacity=".16"></stop><stop offset="100%" stop-color="#176fe5" stop-opacity="0"></stop></linearGradient></defs>${grid}${labels}<path class="area" d="${linePath(pts.map(p=>({x:p.x,y:p.y})))} L ${pts.at(-1).x} ${H-pad.b} L ${pts[0].x} ${H-pad.b} Z"></path><path class="contribLine" d="${linePath(pts.map(p=>({x:p.x,y:p.cy})))}"></path><path class="totalLine" d="${linePath(pts.map(p=>({x:p.x,y:p.y})))}"></path><line class="selectedLine" id="${idPrefix}Line" x1="${pts[0].x}" x2="${pts[0].x}" y1="${pad.t}" y2="${H-pad.b}"></line><circle class="selectedDot" id="${idPrefix}Dot" cx="${pts[0].x}" cy="${pts[0].y}" r="8"></circle><rect class="chartHit" id="${idPrefix}Hit" x="${pad.l}" y="${pad.t}" width="${W-pad.l-pad.r}" height="${H-pad.t-pad.b}"></rect></svg>`}}
function bindChart(hitId,data,chart,update){const hit=document.getElementById(hitId);if(!hit)return;const nearest=e=>{const r=hit.getBoundingClientRect(),px=clamp((e.clientX-r.left)/r.width,0,1),i=Math.round(px*(data.length-1));return clamp(i,0,data.length-1)};let dragging=false;hit.onpointerdown=e=>{dragging=true;document.body.classList.add('charting');try{hit.setPointerCapture(e.pointerId)}catch(_e){}update(nearest(e),false)};hit.onpointermove=e=>{if(dragging)update(nearest(e),false)};hit.onpointerup=e=>{if(!dragging)return;dragging=false;document.body.classList.remove('charting');update(nearest(e),true)};hit.onpointercancel=()=>{dragging=false;document.body.classList.remove('charting')}}
function updateChartSelection(prefix,chart,index){const p=chart.pts[index],line=document.getElementById(`${prefix}Line`),dot=document.getElementById(`${prefix}Dot`);if(line){line.setAttribute('x1',p.x);line.setAttribute('x2',p.x)}if(dot){dot.setAttribute('cx',p.x);dot.setAttribute('cy',p.y)}}
function renderAnalysis(){document.getElementById('analysis').innerHTML=`<div class="segment three"><i class="segmentIndicator ${state.ui.analysisPanel==='allocation'?'i1':state.ui.analysisPanel==='cashflow'?'i2':''}"></i><button data-analysis="performance" class="${state.ui.analysisPanel==='performance'?'active':''}">성과</button><button data-analysis="allocation" class="${state.ui.analysisPanel==='allocation'?'active':''}">비중</button><button data-analysis="cashflow" class="${state.ui.analysisPanel==='cashflow'?'active':''}">현금흐름</button></div><div id="analysisContent"></div>`;document.querySelectorAll('[data-analysis]').forEach(b=>b.onclick=()=>switchAnalysisPanel(b.dataset.analysis));renderAnalysisContent()}
function switchAnalysisPanel(panel){if(state.ui.analysisPanel===panel)return;state.ui.analysisPanel=panel;const root=document.getElementById('analysis');root.querySelectorAll('[data-analysis]').forEach(b=>b.classList.toggle('active',b.dataset.analysis===panel));const ind=root.querySelector('.segmentIndicator');ind.className=`segmentIndicator ${panel==='allocation'?'i1':panel==='cashflow'?'i2':''}`;renderAnalysisContent();animatePanel('analysisContent');save()}
function animatePanel(id){const el=document.getElementById(id);if(!el)return;el.classList.remove('panelSwap');void el.offsetWidth;el.classList.add('panelSwap')}
function renderAnalysisContent(){const el=document.getElementById('analysisContent');if(state.ui.analysisPanel==='performance')renderPerformance(el);else if(state.ui.analysisPanel==='allocation')renderAllocation(el);else renderCashflow(el)}
function renderPerformance(el){const years=Object.keys(state.years).map(Number).sort((a,b)=>a-b),data=years.map(y=>({year:y,...state.years[y]}));if(!data.length){el.innerHTML=`<div class="card empty"><b>성과 데이터가 없어요</b></div>`;return}state.ui.performanceIndex=clamp(Number(state.ui.performanceIndex)||data.length-1,0,data.length-1);const chart=buildChart(data,{yValue:d=>d.end,cValue:d=>d.cumulative,xLabels:data.map((d,i)=>[i,String(d.year)]),idPrefix:'perf'});el.innerHTML=`<div class="stack"><div class="card chartCard"><div class="chartHead"><div><div class="chartTitle">총자산과 순납입</div><div class="chartSub">연도를 누르거나 좌우로 움직여 확인</div></div><div class="legend"><span><i class="a"></i>총자산</span><span><i class="b"></i>순납입</span></div></div><div class="chart">${chart.svg}</div><div class="chartHint" id="perfHint"></div><div class="detailBars"><div class="detailBar"><div class="detailBarTop"><span>총자산</span><b id="perfTotal"></b></div><div class="barTrack"><div class="barFill" id="perfTotalBar"></div></div></div><div class="detailBar"><div class="detailBarTop"><span>누적 순납입</span><b id="perfContrib"></b></div><div class="barTrack"><div class="barFill gray" id="perfContribBar"></div></div></div><div class="detailBar"><div class="detailBarTop"><span>운용증가</span><b id="perfProfit"></b></div><div class="barTrack"><div class="barFill green" id="perfProfitBar"></div></div></div></div></div><div class="card"><table class="table"><thead><tr><th>연도</th><th>총자산</th><th>운용증가</th><th>수익률</th></tr></thead><tbody>${data.slice(-3).reverse().map(d=>`<tr><td>${d.year}</td><td>${man(d.end)}</td><td>${man(d.end-d.cumulative)}</td><td class="${d.return>=0?'good':'bad'}">${pct(d.return)}</td></tr>`).join('')}</tbody></table></div></div>`;const update=(i,commit)=>{const d=data[i],profit=d.end-d.cumulative,max=Math.max(d.end,1);state.ui.performanceIndex=i;updateChartSelection('perf',chart,i);document.getElementById('perfHint').textContent=`${d.year}년 · 총자산 ${man(d.end)} · 수익률 ${pct(d.return)}`;document.getElementById('perfTotal').textContent=fmt(d.end);document.getElementById('perfContrib').textContent=fmt(d.cumulative);document.getElementById('perfProfit').textContent=`${profit>=0?'+':''}${fmt(profit)}`;document.getElementById('perfTotalBar').style.width='100%';document.getElementById('perfContribBar').style.width=`${clamp(d.cumulative/max*100,0,100)}%`;document.getElementById('perfProfitBar').style.width=`${clamp(Math.abs(profit)/max*100,0,100)}%`;if(commit)save()};update(state.ui.performanceIndex,false);bindChart('perfHit',data,chart,update)}
function renderAllocation(el){const totals=classTotals(),total=Object.values(totals).reduce((s,n)=>s+n,0)||1,analysis=lifecycleAnalysis();const rows=state.settings.assetClasses.map(c=>{const cur=(totals[c.id]||0)/total*100,diff=cur-c.target;return {c,cur,diff}});el.innerHTML=`<div class="stack"><div class="card"><div class="row"><div><div class="eyebrow">현재 포트폴리오</div><div class="money small">${analysis.label}</div></div><span class="chip">성장성 자산 ${analysis.growthPct.toFixed(1)}%</span></div>${rows.map(r=>`<div class="allocationRow"><div class="allocationTop"><b>${esc(r.c.name)}</b><span>현재 ${r.cur.toFixed(1)}%</span><b class="${r.diff>2?'bad':r.diff<-2?'blue':''}">${r.diff>0?'+':''}${r.diff.toFixed(1)}%p</b></div><div class="allocBar"><i style="width:${clamp(r.cur,0,100)}%"></i></div></div>`).join('')}</div><div class="card brief"><div class="briefTitle">다음 납입 방향</div><p>${esc(analysis.ageMsg)}<br><b>${esc(analysis.action)}</b></p></div><div class="card"><div class="sectionTitle" style="margin:0 0 10px">계좌별 다음 납입</div>${['pension','irp'].map(k=>{const a=state.accounts[k],amount=state.settings.monthly[k];const under=[...rows].sort((a,b)=>a.diff-b.diff)[0];return `<div class="row" style="padding:11px 0;border-bottom:1px solid var(--line)"><div><b>${esc(a.name)}</b><div class="tiny">${esc(under.c.name)} 우선</div></div><strong>${fmt(amount)}</strong></div>`}).join('')}</div></div>`}
function renderCashflow(el){const years=Object.keys(state.years).map(Number).sort((a,b)=>a-b),thisYear=state.years[CURRENT_YEAR]||{dividend:0,reinvested:0,monthly:Array(12).fill(0)},cash=thisYear.dividend-thisYear.reinvested,avg=thisYear.dividend/Math.max(1,CURRENT_MONTH);const rank=(state.dividendsByAsset[CURRENT_YEAR]||[]).sort((a,b)=>b[1]-a[1]);el.innerHTML=`<div class="stack"><div class="card"><div class="summaryGrid"><div class="summaryBox"><small>올해 받은 금액</small><b>${fmt(thisYear.dividend)}</b></div><div class="summaryBox"><small>재투자</small><b>${fmt(thisYear.reinvested)}</b></div><div class="summaryBox"><small>현금으로 남음</small><b>${fmt(cash)}</b></div><div class="summaryBox"><small>월평균</small><b>${fmt(avg)}</b></div></div></div><div class="card"><div class="sectionTitle" style="margin:0 0 8px">연도별 현금흐름</div><table class="table"><thead><tr><th>연도</th><th>분배금</th><th>전년 대비</th></tr></thead><tbody>${years.slice().reverse().map((y,i,arr)=>{const prev=state.years[y-1]?.dividend||0,change=prev?(state.years[y].dividend/prev-1)*100:0;return `<tr><td>${y}</td><td>${fmt(state.years[y].dividend)}</td><td class="${change>=0?'good':'bad'}">${prev?pct(change):'-'}</td></tr>`}).join('')}</tbody></table></div><div class="card"><div class="sectionTitle" style="margin:0 0 8px">${CURRENT_YEAR} 종목별</div>${rank.length?rank.map(([name,val])=>`<div class="row" style="padding:11px 0;border-bottom:1px solid var(--line)"><span>${esc(name)}</span><b>${fmt(val)}</b></div>`).join(''):`<div class="tiny">아직 기록이 없어요.</div>`}</div></div>`}
function renderFuture(){document.getElementById('future').innerHTML=`<div class="segment two"><i class="segmentIndicator ${state.ui.futurePanel==='withdraw'?'right':''}"></i><button data-future="accum" class="${state.ui.futurePanel==='accum'?'active':''}">적립 결과</button><button data-future="withdraw" class="${state.ui.futurePanel==='withdraw'?'active':''}">수령 계획</button></div><div id="futureContent"></div>`;document.querySelectorAll('[data-future]').forEach(b=>b.onclick=()=>switchFuturePanel(b.dataset.future));renderFutureContent()}
function switchFuturePanel(panel){if(state.ui.futurePanel===panel)return;state.ui.futurePanel=panel;const root=document.getElementById('future');root.querySelectorAll('[data-future]').forEach(b=>b.classList.toggle('active',b.dataset.future===panel));root.querySelector('.segmentIndicator').classList.toggle('right',panel==='withdraw');renderFutureContent();animatePanel('futureContent');save()}
function renderFutureContent(){const el=document.getElementById('futureContent');state.ui.futurePanel==='accum'?renderAccum(el):renderWithdraw(el)}
function renderAccum(el){const data=projection(),retAge=state.profile.retirementAge,stateAge=state.profile.age;let selectedIndex=data.findIndex(d=>d.age===state.ui.futureAge);if(selectedIndex<0)selectedIndex=data.length-1;const ages=[40,50,60,retAge].filter((v,i,a)=>v>=stateAge&&v<=retAge&&a.indexOf(v)===i),chart=buildChart(data,{yValue:d=>d.end,cValue:d=>d.cumulative,xLabels:[0,...ages.map(a=>data.findIndex(d=>d.age===a))].filter((v,i,a)=>v>=0&&a.indexOf(v)===i).map(i=>[i,`${data[i].age}세`]),idPrefix:'future'}),goal=goalStatus();el.innerHTML=`<div class="stack"><div class="card chartCard"><div class="chartHead"><div><div class="chartTitle">장기 자산 경로</div><div class="chartSub">30년 변동 경로 · 개시 전 3년 완화</div></div><div class="legend"><span><i class="a"></i>예상자산</span><span><i class="b"></i>누적납입</span></div></div><div class="chart">${chart.svg}</div><div class="chartHint" id="futureHint"></div><div class="detailBars"><div class="detailBar"><div class="detailBarTop"><span>예상자산</span><b id="futureTotal"></b></div><div class="barTrack"><div class="barFill" id="futureTotalBar"></div></div></div><div class="detailBar"><div class="detailBarTop"><span>누적납입</span><b id="futureContrib"></b></div><div class="barTrack"><div class="barFill gray" id="futureContribBar"></div></div></div><div class="detailBar"><div class="detailBarTop"><span>운용증가</span><b id="futureProfit"></b></div><div class="barTrack"><div class="barFill green" id="futureProfitBar"></div></div></div></div><div class="ageCards">${ages.map(age=>{const d=data.find(x=>x.age===age);return `<button class="ageCard ${age===data[selectedIndex].age?'active':''}" data-age="${age}"><small>${age}세</small><b>${man(d.end)}</b></button>`}).join('')}</div></div><div class="card compact"><div class="goalRow"><div class="goalRing" style="--p:${Math.min(goal.p,100)}"><b>${Math.round(goal.p)}%</b></div><div class="goalText"><b>목표 현재가치 월 ${man(goal.goal)}</b><p>예상 월 ${man(goal.real)}${goal.gap>0?` · ${man(goal.gap)} 부족`:' · 목표 달성권'}</p></div></div></div><div class="card brief"><div class="briefTitle">미래 계산 가정</div><p>적립 수익률 ${state.settings.returnRate}% · 물가 ${state.settings.inflation}% · 수령 중 수익률 ${state.settings.withdrawReturn}% · ${state.settings.withdrawYears}년 수령</p></div></div>`;const update=(i,commit)=>{const d=data[i],max=Math.max(d.end,1);state.ui.futureAge=d.age;updateChartSelection('future',chart,i);document.getElementById('futureHint').textContent=`${d.age}세 · 예상자산 ${man(d.end)} · 누적납입 ${man(d.cumulative)}`;document.getElementById('futureTotal').textContent=fmt(d.end);document.getElementById('futureContrib').textContent=fmt(d.cumulative);document.getElementById('futureProfit').textContent=`${d.operating>=0?'+':''}${fmt(d.operating)}`;document.getElementById('futureTotalBar').style.width='100%';document.getElementById('futureContribBar').style.width=`${clamp(d.cumulative/max*100,0,100)}%`;document.getElementById('futureProfitBar').style.width=`${clamp(Math.abs(d.operating)/max*100,0,100)}%`;document.querySelectorAll('[data-age]').forEach(b=>b.classList.toggle('active',Number(b.dataset.age)===d.age));if(commit)save()};update(selectedIndex,false);bindChart('futureHit',data,chart,update);document.querySelectorAll('[data-age]').forEach(b=>b.onclick=()=>{const i=data.findIndex(d=>d.age===Number(b.dataset.age));if(i>=0)update(i,true)})}
function renderWithdraw(el){const asset=projection().at(-1).end,sims=['dividend','balanced','fixed'].map(k=>withdrawalSim(asset,k)),selected=sims.find(s=>s.key===state.ui.strategy)||sims[1];el.innerHTML=`<div class="stack"><div class="strategyGrid">${sims.map(s=>`<button class="strategyCard ${s.key===selected.key?'active':''}" data-strategy="${s.key}"><b>${esc(s.name)}</b><strong>월 ${man(s.startMonthly)}</strong><p>${esc(s.desc)}</p></button>`).join('')}</div><div class="card"><div class="eyebrow">${selected.name} · 세전 예상</div><div class="money small">월 ${man(selected.startMonthly)}</div><div class="summaryGrid" style="margin-top:14px"><div class="summaryBox"><small>${state.profile.retirementAge+state.settings.withdrawYears}세 잔액</small><b>${man(selected.end)}</b></div><div class="summaryBox"><small>총 수령액</small><b>${man(selected.total)}</b></div></div><div class="tiny" style="margin-top:12px">수령 중 기대수익률 ${state.settings.withdrawReturn}% · ${state.settings.withdrawYears}년 계산</div></div><div class="card"><table class="table"><thead><tr><th>전략</th><th>첫 월수령</th><th>종료 잔액</th></tr></thead><tbody>${sims.map(s=>`<tr><td>${s.name}</td><td>${man(s.startMonthly)}</td><td>${man(s.end)}</td></tr>`).join('')}</tbody></table></div></div>`;document.querySelectorAll('[data-strategy]').forEach(b=>b.onclick=()=>{state.ui.strategy=b.dataset.strategy;renderWithdraw(el);save()})}
function renderSettings(){settingsDraft=clone({profile:state.profile,settings:state.settings});const body=document.getElementById('settingsBody');body.innerHTML=`<div class="sheetNotice">입력값은 저장 버튼을 눌러야 반영돼요. 앱 버전 ${APP_VERSION}</div><div class="settingsSection"><div class="settingsTitle">기본 계획</div><div class="twoFields"><div class="field"><label>현재 나이</label><input id="setAge" type="number" inputmode="numeric" value="${settingsDraft.profile.age}"></div><div class="field"><label>연금 개시 나이</label><input id="setRetAge" type="number" inputmode="numeric" value="${settingsDraft.profile.retirementAge}"></div></div><div class="field"><label>연금저축 월 납입</label><input id="setPension" type="text" inputmode="numeric" value="${Number(settingsDraft.settings.monthly.pension).toLocaleString('ko-KR')}"><div class="fieldHint" id="hintPension"></div></div><div class="field"><label>IRP 월 납입</label><input id="setIrp" type="text" inputmode="numeric" value="${Number(settingsDraft.settings.monthly.irp).toLocaleString('ko-KR')}"><div class="fieldHint" id="hintIrp"></div></div><div class="field"><label>목표 현재가치 월연금</label><input id="setGoal" type="text" inputmode="numeric" value="${Number(settingsDraft.settings.goalMonthly).toLocaleString('ko-KR')}"><div class="fieldHint" id="hintGoal"></div></div></div><div class="settingsSection"><div class="settingsTitle">자산군 목표 비중</div><div id="classRows"></div><button class="btn full" id="addClass" style="margin-top:10px">자산군 추가</button><div class="targetSum" id="targetSum"></div></div><div class="settingsSection"><button class="disclosure" id="assumptionBtn"><span>미래 계산 가정</span><span>⌄</span></button><div class="disclosurePanel" id="assumptionPanel"><div><div class="twoFields"><div class="field"><label>적립 기대수익률</label><input id="setReturn" type="number" step="0.1" value="${settingsDraft.settings.returnRate}"></div><div class="field"><label>물가상승률</label><input id="setInflation" type="number" step="0.1" value="${settingsDraft.settings.inflation}"></div><div class="field"><label>수령 기간</label><input id="setYears" type="number" value="${settingsDraft.settings.withdrawYears}"></div><div class="field"><label>수령 중 수익률</label><input id="setWithdrawReturn" type="number" step="0.1" value="${settingsDraft.settings.withdrawReturn}"></div></div></div></div></div><div id="settingsError" class="error"></div><div class="saveBar"><button class="btn primary full" id="saveSettings">저장</button></div>`;renderClassRows();const moneyIds=['setPension','setIrp','setGoal'];moneyIds.forEach(id=>{const input=document.getElementById(id),hint=document.getElementById(id.replace('set','hint'));const update=()=>{const n=parseMoney(input.value);input.value=n?Number(n).toLocaleString('ko-KR'):'';hint.textContent=n?`약 ${man(n)}`:''};input.addEventListener('blur',update);update()});document.getElementById('addClass').onclick=()=>{settingsDraft.settings.assetClasses.push({id:`custom-${Date.now()}`,name:'새 자산군',target:0,riskWeight:50});renderClassRows()};document.getElementById('assumptionBtn').onclick=()=>document.getElementById('assumptionPanel').classList.toggle('open');document.getElementById('saveSettings').onclick=saveSettingsDraft;}
function renderClassRows(){const el=document.getElementById('classRows');el.innerHTML=settingsDraft.settings.assetClasses.map((c,i)=>`<div class="classRow"><input class="className" data-i="${i}" maxlength="12" value="${esc(c.name)}" aria-label="자산군 이름"><input class="classTarget" data-i="${i}" type="number" inputmode="decimal" min="0" max="100" step="0.1" value="${c.target}" aria-label="목표 비중"><button class="removeBtn" data-remove="${i}" aria-label="자산군 삭제">×</button></div>`).join('');const sync=()=>{document.querySelectorAll('.className').forEach(x=>settingsDraft.settings.assetClasses[x.dataset.i].name=x.value.trim());document.querySelectorAll('.classTarget').forEach(x=>settingsDraft.settings.assetClasses[x.dataset.i].target=Number(x.value)||0);const sum=settingsDraft.settings.assetClasses.reduce((s,c)=>s+Number(c.target||0),0),sumEl=document.getElementById('targetSum');sumEl.textContent=`목표 합계 ${sum.toFixed(1)}%`;sumEl.className=`targetSum ${Math.abs(sum-100)<.01?'ok':'bad'}`};document.querySelectorAll('.className,.classTarget').forEach(x=>x.oninput=sync);document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{sync();const c=settingsDraft.settings.assetClasses[Number(b.dataset.remove)],used=Object.values(state.accounts).some(a=>a.holdings.some(h=>h.class===c.id));if(used)return toast('보유상품이 연결돼 있어 삭제할 수 없어요');settingsDraft.settings.assetClasses.splice(Number(b.dataset.remove),1);renderClassRows()});sync()}
function parseMoney(v){return Number(String(v??'').replace(/[^0-9.-]/g,''))||0}
function saveSettingsDraft(){const err=document.getElementById('settingsError'),age=Number(document.getElementById('setAge').value),ret=Number(document.getElementById('setRetAge').value),p=parseMoney(document.getElementById('setPension').value),i=parseMoney(document.getElementById('setIrp').value),goal=parseMoney(document.getElementById('setGoal').value),rate=Number(document.getElementById('setReturn').value),infl=Number(document.getElementById('setInflation').value),years=Number(document.getElementById('setYears').value),wr=Number(document.getElementById('setWithdrawReturn').value);document.querySelectorAll('.className').forEach(x=>settingsDraft.settings.assetClasses[x.dataset.i].name=x.value.trim());document.querySelectorAll('.classTarget').forEach(x=>settingsDraft.settings.assetClasses[x.dataset.i].target=Number(x.value));const names=settingsDraft.settings.assetClasses.map(c=>c.name),sum=settingsDraft.settings.assetClasses.reduce((s,c)=>s+c.target,0);let msg='';if(age<18||age>100)msg='현재 나이는 18~100세로 입력하세요.';else if(ret<18||ret>90)msg='연금 개시 나이는 18~90세로 입력하세요.';else if([p,i,goal].some(n=>n<0||n>100000000))msg='금액은 0원 이상으로 입력하세요.';else if(!Number.isFinite(rate)||rate<-20||rate>20)msg='적립 기대수익률은 -20~20%로 입력하세요.';else if(!Number.isFinite(infl)||infl<0||infl>10)msg='물가상승률은 0~10%로 입력하세요.';else if(years<5||years>50)msg='수령 기간은 5~50년으로 입력하세요.';else if(!Number.isFinite(wr)||wr<-10||wr>15)msg='수령 중 수익률은 -10~15%로 입력하세요.';else if(names.some(n=>!n)||new Set(names).size!==names.length)msg='자산군 이름은 비워두거나 중복할 수 없어요.';else if(names.some(n=>n.length>12))msg='자산군 이름은 12자 이내로 입력하세요.';else if(settingsDraft.settings.assetClasses.some(c=>c.target<0||c.target>100)||Math.abs(sum-100)>.01)msg='자산군 목표 비중 합계를 100%로 맞춰주세요.';if(msg){err.textContent=msg;return}settingsDraft.profile={age,retirementAge:ret};settingsDraft.settings={...settingsDraft.settings,monthly:{pension:p,irp:i},goalMonthly:goal,returnRate:rate,inflation:infl,withdrawYears:years,withdrawReturn:wr};state.profile=clone(settingsDraft.profile);state.settings=clone(settingsDraft.settings);state.ui.futureAge=clamp(state.ui.futureAge,age,ret);save();closeSheet('settingsSheet');renderAll();toast('설정을 저장했어요')}
function quickForm(type){document.getElementById('quickSheet').classList.remove('open');const title=document.getElementById('formTitle'),body=document.getElementById('formBody');if(type==='contribution')renderContributionForm(title,body);else if(type==='snapshot')renderSnapshotForm(title,body);else renderDetailForm(title,body);openSheet('formSheet',true)}
function renderContributionForm(title,body){const s=currentContributionStatus(),planned=['pension','irp'].filter(k=>Number(state.settings.monthly[k])>0),missing=planned.filter(k=>!s[k]);title.textContent='이번 달 납입';if(!planned.length){body.innerHTML=`<div class="settingsInfo">이번 달 납입 계획이 없어요. 설정에서 월 납입액을 정하세요.</div>`;return}if(!missing.length){body.innerHTML=`<div class="settingsInfo">이번 달 계획된 납입이 모두 기록됐어요.</div>`;return}body.innerHTML=`<div class="settingsInfo">금액 변경은 설정에서만 해요. 아직 기록되지 않은 계좌만 표시합니다.</div>${missing.map(k=>`<label class="quickItem" style="margin-top:10px"><input type="checkbox" data-contrib="${k}" checked style="width:20px;height:20px"><span><b>${state.accounts[k].name}</b><small>${fmt(state.settings.monthly[k])}</small></span><span></span></label>`).join('')}<button class="btn primary full" id="applyContribution" style="margin-top:14px">선택 계좌 기록</button>`;document.getElementById('applyContribution').onclick=()=>{const keys=[...document.querySelectorAll('[data-contrib]:checked')].map(x=>x.dataset.contrib);if(!keys.length)return toast('기록할 계좌를 선택하세요');const row=ensureYear(),status=state.runtime.contributions[CURRENT_KEY]||{pension:false,irp:false};for(const k of keys){if(status[k])continue;const amount=state.settings.monthly[k];state.accounts[k].principal+=amount;state.accounts[k].cash+=amount;row.contribution+=amount;status[k]=true}state.runtime.contributions[CURRENT_KEY]=status;updateYearFromAssets();save();closeSheet('formSheet');renderAll();toast('이번 달 납입을 기록했어요')}}
function parseHoldingText(text){return text.split(/\r?\n/).map(line=>line.trim()).filter(Boolean).map((line,lineIndex)=>{let p;if(line.includes('|'))p=line.split('|');else if(line.includes('\t'))p=line.split('\t');else p=line.split(/\s{2,}/);p=p.map(x=>x.trim());const num=x=>{const raw=String(x||'').replace(/[^0-9.-]/g,'');return raw===''?0:Number(raw)};return {line:lineIndex+1,name:p[0]||'',qty:num(p[1]),value:num(p[2]),cost:num(p[3]),className:p[4]||''}}).filter(x=>x.name)}
function renderSnapshotForm(title,body){title.textContent='자산현황 갱신';body.innerHTML=`<div class="sheetNotice">계좌 총액만 입력하면 기존 보유상품은 유지하고 현금만 맞춰요. 종목표를 붙여넣으면 보유상품 목록을 새 내용으로 교체합니다.</div><div class="field"><label>계좌</label><select id="snapAccount"><option value="pension">연금저축</option><option value="irp">IRP</option></select></div><div class="field"><label>현재 계좌 총액 · 선택</label><input id="snapTotal" inputmode="numeric" placeholder="예: 35,000,000"><div class="inputHelp">종목표 없이 총액만 입력해도 됩니다.</div></div><div class="field"><label>여러 종목 붙여넣기</label><textarea id="snapText" rows="7" placeholder="종목명 | 수량 | 평가금액 | 원금 | 자산군\nRISE 미국나스닥100 | 176 | 14,000,000 | 10,800,000 | 성장주"></textarea></div><div class="settingsInfo" id="snapPreview">붙여넣으면 추가·변경·제외 예정 항목을 확인할 수 있어요.</div><button class="btn primary full" id="applySnapshot" style="margin-top:14px">확인한 내용 반영</button>`;const getData=()=>{const key=document.getElementById('snapAccount').value,a=state.accounts[key],rows=parseHoldingText(document.getElementById('snapText').value),total=parseMoney(document.getElementById('snapTotal').value),old=new Map(a.holdings.map(h=>[h.name,h])),names=rows.map(r=>r.name),dupes=[...new Set(names.filter((n,i)=>names.indexOf(n)!==i))],invalid=rows.filter(r=>![r.qty,r.value,r.cost].every(Number.isFinite)||r.qty<0||r.value<0||r.cost<0),added=rows.filter(r=>!old.has(r.name)),changed=rows.filter(r=>old.has(r.name)&&(old.get(r.name).value!==r.value||old.get(r.name).cost!==r.cost||old.get(r.name).qty!==r.qty)),removed=a.holdings.filter(h=>rows.length&&!rows.some(r=>r.name===h.name)),sum=rows.reduce((s,r)=>s+(Number.isFinite(r.value)?r.value:0),0),existingSum=a.holdings.reduce((s,h)=>s+h.value,0),diff=total?(rows.length?total-sum:total-existingSum):null;return {key,a,rows,total,dupes,invalid,added,changed,removed,sum,existingSum,diff}};const update=()=>{const d=getData(),names=d.rows.slice(0,3).map(r=>esc(r.name)).join(' · '),issues=[];if(d.dupes.length)issues.push(`중복 종목 ${d.dupes.length}개`);if(d.invalid.length)issues.push(`잘못된 숫자 ${d.invalid.length}줄`);if(d.total&&d.diff<0)issues.push('계좌 총액보다 상품 합계가 큼');document.getElementById('snapPreview').innerHTML=`<b>${d.rows.length}개 종목 인식</b><div class="previewList"><div class="previewItem"><span>추가 / 변경 / 제외</span><b>${d.added.length} / ${d.changed.length} / ${d.removed.length}</b></div><div class="previewItem"><span>${d.rows.length?'종목 평가금 합계':'기존 종목 평가금'}</span><b>${fmt(d.rows.length?d.sum:d.existingSum)}</b></div>${d.total?`<div class="previewItem"><span>계좌 총액과 차이(현금)</span><b class="${d.diff<0?'bad':''}">${fmt(d.diff)}</b></div>`:`<div class="previewItem"><span>현금</span><b>기존값 유지</b></div>`}${issues.length?`<div class="previewItem"><span>확인 필요</span><b class="bad">${issues.join(' · ')}</b></div>`:''}</div>${names?`<div class="snapshotNames">${names}${d.rows.length>3?' 외':''}</div>`:''}`};['snapText','snapTotal'].forEach(id=>document.getElementById(id).addEventListener('input',update));document.getElementById('snapAccount').addEventListener('change',update);update();document.getElementById('applySnapshot').onclick=()=>{const d=getData();if(!d.rows.length&&!d.total)return toast('계좌 총액이나 종목 표를 입력하세요');if(d.dupes.length)return toast(`중복 종목을 정리하세요: ${d.dupes.slice(0,2).join(', ')}`);if(d.invalid.length)return toast(`${d.invalid[0].line}번째 줄의 수량·금액을 확인하세요`);if(d.total&&d.diff<0)return toast(d.rows.length?'종목 합계가 계좌 총액보다 커요':'계좌 총액이 기존 종목 합계보다 작아요');if(d.rows.length){archiveMissingHoldings(d.key,d.rows,'snapshot-text-replaced');const old=Object.fromEntries(d.a.holdings.map(h=>[h.name,h]));d.a.holdings=d.rows.map(r=>{const prev=old[r.name]||{},cls=state.settings.assetClasses.find(c=>c.name===r.className||c.id===r.className)?.id||prev.class||state.settings.assetClasses[0].id;return prepareHolding(d.key,{...prev,name:r.name,qty:r.qty,value:r.value,cost:r.cost||prev.cost||r.value,class:cls,dividend:prev.dividend||0,realized:prev.realized||0,risk:d.key==='irp'?(prev.risk??state.settings.assetClasses.find(c=>c.id===cls)?.riskWeight>=70):undefined},prev)})}if(d.total)d.a.cash=Math.max(0,d.total-(d.rows.length?d.sum:d.existingSum));state.ui.accountView=d.key;state.lastUpdated=localDisplayDate(new Date());updateYearFromAssets();save();closeSheet('formSheet');renderAll();toast(`${d.a.name} 자산현황을 갱신했어요`)}}
function renderDetailForm(title,body){title.textContent='배당·매도 기록';body.innerHTML=`<div class="field"><label>종류</label><select id="detailType"><option value="dividend">배당·분배금</option><option value="sale">매도 확정손익</option></select></div><div class="field"><label>계좌</label><select id="detailAccount"><option value="pension">연금저축</option><option value="irp">IRP</option></select></div><div class="field"><label>상품</label><select id="detailAsset"></select><div class="inputHelp" id="detailAssetHelp"></div></div><div class="field"><label id="detailAmountLabel">받은 금액</label><input id="detailAmount" inputmode="decimal" placeholder="예: 120,000"><div class="inputHelp" id="detailAmountHelp">배당은 0원보다 큰 금액만 기록해요.</div></div><button class="btn primary full" id="applyDetail" style="margin-top:14px">기록</button>`;const fill=()=>{const key=document.getElementById('detailAccount').value,items=state.accounts[key].holdings,select=document.getElementById('detailAsset'),help=document.getElementById('detailAssetHelp'),btn=document.getElementById('applyDetail');select.innerHTML=items.length?items.map((h,i)=>`<option value="${i}">${esc(h.name)}</option>`).join(''):'<option value="">등록된 상품 없음</option>';select.disabled=!items.length;btn.disabled=!items.length;help.textContent=items.length?'':'먼저 자산현황을 입력하세요.'};const syncKind=()=>{const sale=document.getElementById('detailType').value==='sale';document.getElementById('detailAmountLabel').textContent=sale?'확정손익':'받은 금액';document.getElementById('detailAmount').placeholder=sale?'예: 120,000 또는 -80,000':'예: 120,000';document.getElementById('detailAmountHelp').textContent=sale?'수익은 양수, 손실은 음수로 입력하세요.':'배당은 0원보다 큰 금액만 기록해요.'};document.getElementById('detailAccount').onchange=fill;document.getElementById('detailType').onchange=syncKind;fill();syncKind();document.getElementById('applyDetail').onclick=()=>{const amt=parseMoney(document.getElementById('detailAmount').value),key=document.getElementById('detailAccount').value,i=Number(document.getElementById('detailAsset').value),h=state.accounts[key].holdings[i],kind=document.getElementById('detailType').value;if(!h)return toast('먼저 상품을 등록하세요');if(kind==='dividend'&&amt<=0)return toast('배당 금액은 0원보다 크게 입력하세요');if(kind==='sale'&&amt===0)return toast('확정손익을 입력하세요');const row=ensureYear();if(kind==='dividend'){row.dividend+=amt;row.monthly[CURRENT_MONTH-1]+=amt;h.dividend=(h.dividend||0)+amt;state.dividendsByAsset[CURRENT_YEAR]=state.dividendsByAsset[CURRENT_YEAR]||[];const found=state.dividendsByAsset[CURRENT_YEAR].find(x=>x[0]===h.name);found?found[1]+=amt:state.dividendsByAsset[CURRENT_YEAR].push([h.name,amt])}else{row.realized=(row.realized||0)+amt;h.realized=(h.realized||0)+amt}state.ui.accountView=key;save();closeSheet('formSheet');renderAll();toast(kind==='dividend'?'배당을 기록했어요':'확정손익을 기록했어요')}}
